<?php
declare(strict_types=1);
putenv('RUMOHUB_ENABLED=0');putenv('RUMOHUB_BENEFITS=0');putenv('RUMO10_WORLD_CALENDAR=1');putenv('RUMO10_WORLD_FIXTURES=1');require dirname(__DIR__).'/app/bootstrap.php';
$checks=0;function prcheck(bool $x,string $why):void{global $checks;$checks++;if(!$x)throw new RuntimeException($why);}
$g=PernambucoPotiguarTrial::create(857300,'expresso');$members=$g['memberships'];
WorldSeason::scope($g,function()use(&$g){foreach($g['competitions'] as &$t)Competition::finish($t,$g);unset($t);NationalPyramid::close($g);
foreach(['pe-a1','rn-a1'] as $id){$t=$g['competitions'][$id];$c=$g['world_reference'][$id]['definition'];prcheck(count($t['matches'])===38,'38 jogos por estadual');prcheck(StateResultProof::verify($c,$t),'prova integral '.$id);prcheck(count(array_unique($t['final_ranking']))===8,'oito posições distintas');prcheck(count($t['relegated'])===($id==='pe-a1'?0:2),'descenso específico da edição');
$initial=$t['initial_ranking'];$order=array_flip($initial);$w=$t['state_phase_winners']['playoff'];if($id==='rn-a1')usort($w,fn($a,$b)=>$order[$a]<=>$order[$b]);foreach([[0,1],[1,0]] as $tie=>[$seed,$wi]){ $games=array_values(array_filter($t['matches'],fn($m)=>$m['phase']==='semifinal'&&$m['tie']===$tie));prcheck($games[1]['home']===$initial[$seed]&&$games[1]['away']===$w[$wi],'bye e cruzamento '.$id);}
if($id==='pe-a1'){foreach([[$t['state_eliminated'][1],2],[$t['state_eliminated'][0],4]] as [$clubs,$at]){usort($clubs,fn($a,$b)=>$order[$a]<=>$order[$b]);prcheck(array_slice($t['final_ranking'],$at,2)===$clubs,'eliminados pela primeira fase');}}
else{$rows=ConfiguredStateCompetition::standings($t,null,null,true);foreach($rows as $row){$expected=count(array_filter($t['matches'],fn($m)=>in_array($m['phase'],['liga','semifinal'],true)&&in_array($row['team'],[$m['home'],$m['away']],true)));prcheck($row['played']===$expected,'campanha não inclui playoff/final');}$eligible=array_values(array_diff(array_slice($initial,0,6),array_slice($t['final_ranking'],0,2)));prcheck(array_slice($t['final_ranking'],2,4)===array_column(ConfiguredStateCompetition::standings($t,$eligible,null,true),'team'),'3–6 campanha exclui playoff');prcheck(array_slice($t['final_ranking'],-2)===array_slice($initial,-2),'7/8 preservados');}
$bad=$t;$bad['final_ranking']=array_reverse($bad['final_ranking']);prcheck(!StateResultProof::verify($c,$bad),'adulteração rejeitada');
}
});
// A high-scoring playoff must not contaminate the RN campaign or PE initial-phase ranking.
foreach(['pe-a1','rn-a1'] as $id){$t=$g['competitions'][$id];WorldSeason::scope($g,function()use($id,$t){$before=ConfiguredStateCompetition::standings($t,null,$id==='pe-a1'?'liga':null,true);$changed=$t;foreach($changed['matches'] as &$m)if($m['phase']==='playoff'){$m['hg']=50;$m['ag']=0;}unset($m);prcheck(ConfiguredStateCompetition::standings($changed,null,$id==='pe-a1'?'liga':null,true)===$before,'playoff artificial não muda campanha filtrada');});}
// A definition with an unknown campaign phase must be rejected before any match is created.
foreach(['unknown_phase','duplicate_phase','invalid_basis','unscoped_rank'] as $case){$c=PernambucoPotiguarTrial::reference()['definitions']['rn-a1'];if($case==='unknown_phase')$c['state_engine']['campaign_phases'][]='inexistente';if($case==='duplicate_phase')$c['state_engine']['campaign_phases'][]='liga';if($case==='invalid_basis')$c['state_engine']['eliminated_basis']='overall';if($case==='unscoped_rank')unset($c['state_engine']['campaign_phases']);try{ConfiguredStateCompetition::validate($c,$c['teams']);throw new LogicException('Contrato inválido aceito');}catch(RuntimeException $e){prcheck(true,'contrato ambíguo rejeitado');}}
// A bye-free side gets no extra campaign credit from the playoff; final home is checked independently.
WorldSeason::scope($g,function()use($g){$t=$g['competitions']['rn-a1'];$final=array_values(array_filter($t['matches'],fn($m)=>$m['phase']==='final'));$teams=[$final[0]['home'],$final[0]['away']];$raw=array_values(array_filter($t['matches'],fn($m)=>in_array($m['phase'],['liga','semifinal'],true)));$table=Schedule::table($raw,$teams);if($table[0]['points']!==$table[1]['points'])prcheck($final[1]['home']===$table[0]['team'],'mando final por pontos sem playoff');foreach($t['matches'] as $m)if($m['phase']==='playoff'&&$m['round']===9){$order=array_flip($t['initial_ranking']);prcheck($order[$m['home']]<$order[$m['away']],'volta playoff pelo índice inicial');}});
$rows=StateQualification::recordMany($g,['AL','PI','RO','BA','ES','PE','RN']);$saved=$g;prcheck(StateQualification::recordMany($g,array_keys($rows))==$rows&&$g===$saved,'recibos imutáveis/idempotentes');$audit=FutureSerieDAdmission::record($g);prcheck($audit['federation_missing_total']===64-array_sum(array_column($rows,'candidate_count')),'déficit de um único save');prcheck($g['memberships']===$members&&$audit['blocked'],'sem inscrição/renovação');
$defs=array_map(fn($p)=>$p['definition'],$g['world_reference']);prcheck(PernambucoPotiguarTrial::validatesBudget($g,$defs,$members),'budget estrito');unset($defs['rn-a1']);prcheck(!PernambucoPotiguarTrial::validatesBudget($g,$defs,$members),'budget adulterado rejeitado');
$dir=dirname(__DIR__).'/Docs/mundializacao-v07/expansao-estadual/pe-rn';if(!is_dir($dir))mkdir($dir,0777,true);file_put_contents($dir.'/sports.json',json_encode(['checks'=>$checks,'rows'=>$rows,'admission'=>$audit,'games'=>['PE'=>38,'RN'=>38],'national_renewals'=>0,'entries'=>0,'peak_memory_bytes'=>memory_get_peak_usage(true)],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo "OK: $checks verificações PE/RN.\n";
